// Playwright config for the Stagetimer regression harness. Dev-only, never deployed.
//
// Env:
//   BASE_ROOT  directory served as the site (default: this checkout). The booth
//              baseline is generated by serving an export of commit 845eb0d.
//   ST_PORT    port for the static server (default 5599). Each worktree that runs
//              tests in parallel needs its own port; we never reuse a server that
//              is already listening, so a port clash fails loudly instead of
//              silently testing another tree.
//   ST_BROWSERS  comma list to restrict engines, e.g. "chromium" (default: chromium,webkit).
const { defineConfig, devices } = require('@playwright/test');
const fs = require('fs');
const os = require('os');
const path = require('path');

// Browser cache fallback. The shared default cache (~/Library/Caches/ms-playwright)
// can be locked by a parallel `playwright install` from another agent. If the
// browsers this @playwright/test needs are missing there but present in the
// harness cache (~/Library/Caches/ms-playwright-st, filled with
// `PLAYWRIGHT_BROWSERS_PATH=~/Library/Caches/ms-playwright-st npx playwright install chromium webkit`),
// use that. Workers are forked after this file loads, so they inherit it.
if (!process.env.PLAYWRIGHT_BROWSERS_PATH) {
  try {
    const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, 'node_modules', 'playwright-core', 'browsers.json'), 'utf8'));
    const want = manifest.browsers.filter((b) => ['chromium', 'chromium-headless-shell', 'webkit'].includes(b.name))
      .map((b) => ({ ...b, name: b.name.replace(/-/g, '_') }));
    const has = (dir) => want.every((b) => fs.existsSync(path.join(dir, `${b.name}-${b.revision}`)));
    const def = path.join(os.homedir(), 'Library', 'Caches', 'ms-playwright');
    const alt = path.join(os.homedir(), 'Library', 'Caches', 'ms-playwright-st');
    if (!has(def) && has(alt)) process.env.PLAYWRIGHT_BROWSERS_PATH = alt;
  } catch (_) { /* fall back to Playwright's own lookup */ }
}

const PORT = Number(process.env.ST_PORT || 5599);
const BASE_URL = `http://127.0.0.1:${PORT}`;
const ENGINES = (process.env.ST_BROWSERS || 'chromium,webkit').split(',').map((s) => s.trim()).filter(Boolean);

const shared = {
  baseURL: BASE_URL,
  timezoneId: 'Europe/Amsterdam',
  locale: 'nl-NL',
  serviceWorkers: 'block',
  colorScheme: 'dark',
  deviceScaleFactor: 1,
  trace: 'retain-on-failure',
  screenshot: 'only-on-failure',
};

const engineDevice = { chromium: devices['Desktop Chrome'], webkit: devices['Desktop Safari'] };

const projects = [];
for (const engine of ENGINES) {
  const dev = { ...engineDevice[engine], ...shared, viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 };
  projects.push({
    name: engine,
    testDir: './tests',
    testIgnore: ['booth/**', 'support/**'],
    use: dev,
  });
  projects.push({
    name: `booth-${engine}`,
    testDir: './tests/booth',
    use: dev,
  });
}

module.exports = defineConfig({
  testDir: './tests',
  outputDir: './test-results',
  snapshotPathTemplate: '{testDir}/__screenshots__/{testFileName}/{projectName}/{arg}-{platform}{ext}',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: 0,
  workers: process.env.ST_WORKERS ? Number(process.env.ST_WORKERS) : undefined,
  timeout: 60_000,
  expect: {
    timeout: 10_000,
    toHaveScreenshot: {
      // Pixel-exact. Animations: Playwright's default 'disabled' (finite CSS
      // transitions jump to their end state, infinite ones such as the
      // last-30-s blink and the cue pulse rest at their first keyframe). The
      // computed animation itself is guarded by the style-fingerprint snapshots.
      maxDiffPixels: 0,
      threshold: 0,
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
    },
  },
  reporter: process.env.CI ? [['list'], ['html', { open: 'never' }]] : [['list']],
  webServer: {
    command: 'node tests/support/static-server.mjs',
    url: `${BASE_URL}/__harness`,
    reuseExistingServer: false,
    timeout: 20_000,
    env: { ST_PORT: String(PORT), BASE_ROOT: process.env.BASE_ROOT || '.' },
    stdout: 'ignore',
    stderr: 'pipe',
  },
  projects,
});
